using Irony.Parsing;
using Roboteq.MicroBasic.Compiler.CompilerUnits;

namespace Roboteq.MicroBasic.Compiler;

[Language("MicroBasic", "1.0", "Roboteq MicroBasic")]
public class MicroBasicGrammar : Grammar
{
	public MicroBasicGrammar()
		: base(caseSensitive: false)
	{
		GrammarComments = "Roboteq MicroBasic Compiler.";
		CommentTerminal commentTerminal = new CommentTerminal("Comment", "'", "\r\n", "\r", "\n");
		NonGrammarTerminals.Add(commentTerminal);
		NumberLiteral numberLiteral = new NumberLiteral("Number", NumberOptions.IntOnly);
		numberLiteral.AddPrefix("0x", NumberOptions.Hex);
		numberLiteral.AddPrefix("0b", NumberOptions.Binary);
		numberLiteral.AstNodeType = typeof(NumberCompilerUnit);
		StringLiteral stringLiteral = TerminalFactory.CreateCSharpString("StringLitral");
		stringLiteral.AstNodeType = typeof(StringCompilerUnit);
		IdentifierTerminal identifierTerminal = new IdentifierTerminal("Identifier");
		NonTerminal nonTerminal = new NonTerminal("LineTerminator", NewLine | Eof);
		NonTerminal nonTerminal2 = new NonTerminal("Program", typeof(CompilerUnit));
		NonTerminal nonTerminal3 = new NonTerminal("DirectivesOpt");
		NonTerminal nonTerminal4 = new NonTerminal("ProgramBody");
		NonTerminal nonTerminal5 = new NonTerminal("Directives", typeof(CompilerUnit));
		NonTerminal nonTerminal6 = new NonTerminal("Directive", typeof(DirectiveCompilerUnit));
		NonTerminal nonTerminal7 = new NonTerminal("Script");
		NonTerminal nonTerminal8 = new NonTerminal("AnonymousScript", typeof(ScriptCompilerUnit));
		NonTerminal nonTerminal9 = new NonTerminal("ScriptBody");
		NonTerminal nonTerminal10 = new NonTerminal("Variable", typeof(VariableCompilerUnit));
		NonTerminal nonTerminal11 = new NonTerminal("VariableIndex");
		NonTerminal nonTerminal12 = new NonTerminal("FunctionCall", typeof(FunctionCompilerUnit));
		NonTerminal nonTerminal13 = new NonTerminal("SubCall", typeof(SubCompilerUnit));
		NonTerminal nonTerminal14 = new NonTerminal("ParamList", typeof(CompilerUnit));
		NonTerminal nonTerminal15 = new NonTerminal("Print", typeof(PrintCompilerUnit));
		NonTerminal nonTerminal16 = new NonTerminal("PrintExpr");
		NonTerminal nonTerminal17 = new NonTerminal("PrintBoolExpr", typeof(ToBoolCompilerUnit));
		NonTerminal nonTerminal18 = new NonTerminal("PrintParams", typeof(CompilerUnit));
		NonTerminal nonTerminal19 = new NonTerminal("Statements", typeof(StatementCompilerUnit));
		NonTerminal nonTerminal20 = new NonTerminal("Statement");
		NonTerminal nonTerminal21 = new NonTerminal("NonBlockStatement");
		NonTerminal nonTerminal22 = new NonTerminal("Assignment", typeof(AssignmentCompilerUnit));
		NonTerminal nonTerminal23 = new NonTerminal("AssignmentOperator", "assignment operator");
		NonTerminal nonTerminal24 = new NonTerminal("Expression");
		NonTerminal nonTerminal25 = new NonTerminal("Term");
		NonTerminal nonTerminal26 = new NonTerminal("LogicalConstant", typeof(LogicalConstantCompilerUnit));
		NonTerminal nonTerminal27 = new NonTerminal("ParantheseExpression");
		NonTerminal nonTerminal28 = new NonTerminal("Inc/Dec", typeof(IncCompilerUnit));
		NonTerminal nonTerminal29 = new NonTerminal("Inc/Dec", typeof(IncCompilerUnit));
		NonTerminal nonTerminal30 = new NonTerminal("Inc/DecOperator");
		NonTerminal nonTerminal31 = new NonTerminal("Inc/Dec Call", typeof(IncCallCompilerUnit));
		NonTerminal nonTerminal32 = new NonTerminal("Inc/Dec Call", typeof(IncCallCompilerUnit));
		NonTerminal nonTerminal33 = new NonTerminal("AndExpr");
		NonTerminal nonTerminal34 = new NonTerminal("NotExpr");
		NonTerminal nonTerminal35 = new NonTerminal("CompareExpr");
		NonTerminal nonTerminal36 = new NonTerminal("CompareOp");
		NonTerminal nonTerminal37 = new NonTerminal("ShiftExpr");
		NonTerminal nonTerminal38 = new NonTerminal("AddExpr");
		NonTerminal nonTerminal39 = new NonTerminal("ModulusExpr");
		NonTerminal nonTerminal40 = new NonTerminal("MultExpr");
		NonTerminal nonTerminal41 = new NonTerminal("NegateExpr");
		NonTerminal nonTerminal42 = new NonTerminal("OrOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal43 = new NonTerminal("AndOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal44 = new NonTerminal("NotOperation", typeof(UnaryCompilerUnit));
		NonTerminal nonTerminal45 = new NonTerminal("CompareOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal46 = new NonTerminal("ShiftOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal47 = new NonTerminal("AddOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal48 = new NonTerminal("ModulusOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal49 = new NonTerminal("MultOperation", typeof(BinaryCompilerUnit));
		NonTerminal nonTerminal50 = new NonTerminal("NegateOperation", typeof(UnaryCompilerUnit));
		NonTerminal nonTerminal51 = new NonTerminal("Declaration", typeof(DeclareCompilerUnit));
		NonTerminal nonTerminal52 = new NonTerminal("DataType");
		NonTerminal nonTerminal53 = new NonTerminal("Exit/Continue", typeof(ExitContinueCompilerUnit));
		NonTerminal nonTerminal54 = new NonTerminal("Exit/Continue Key");
		NonTerminal nonTerminal55 = new NonTerminal("Exit/Continue Option");
		NonTerminal nonTerminal56 = new NonTerminal("Goto", typeof(GotoCompilerUnit));
		NonTerminal nonTerminal57 = new NonTerminal("Goto Option");
		NonTerminal nonTerminal58 = new NonTerminal("Label", typeof(LabelCompilerUnit));
		NonTerminal nonTerminal59 = new NonTerminal("Return", typeof(SingleCommandCompilerUnit));
		NonTerminal nonTerminal60 = new NonTerminal("Terminate", typeof(SingleCommandCompilerUnit));
		NonTerminal nonTerminal61 = new NonTerminal("IF");
		NonTerminal nonTerminal62 = new NonTerminal("Non-BlockIf", typeof(NonBlockIfCompilerUnit));
		NonTerminal nonTerminal63 = new NonTerminal("Non-BlockElseOpt");
		NonTerminal nonTerminal64 = new NonTerminal("BlockIf", typeof(BlockIfCompilerUnit));
		NonTerminal nonTerminal65 = new NonTerminal("ThenOp");
		NonTerminal nonTerminal66 = new NonTerminal("ElseIf", typeof(ElseIfCompilerUnit));
		NonTerminal nonTerminal67 = new NonTerminal("Else", typeof(ElseCompilerUnit));
		NonTerminal nonTerminal68 = new NonTerminal("ForLoop", "for loop", typeof(ForCompilerUnit));
		NonTerminal nonTerminal69 = new NonTerminal("NewFor", typeof(ForCompilerUnit));
		NonTerminal nonTerminal70 = new NonTerminal("Step");
		NonTerminal nonTerminal71 = new NonTerminal("Evaluate");
		NonTerminal nonTerminal72 = new NonTerminal("VariableOpt");
		NonTerminal nonTerminal73 = new NonTerminal("EvalExpr");
		NonTerminal nonTerminal74 = new NonTerminal("ConditionalLoop");
		NonTerminal nonTerminal75 = new NonTerminal("DoTestLoop", typeof(ConditionalLoopCompilerUnit));
		NonTerminal nonTerminal76 = new NonTerminal("DoLoopTest", typeof(ConditionalLoopCompilerUnit));
		NonTerminal nonTerminal77 = new NonTerminal("WhileLoop", typeof(ConditionalLoopCompilerUnit));
		NonTerminal nonTerminal78 = new NonTerminal("LoopType");
		nonTerminal2.Rule = nonTerminal3 + nonTerminal4;
		nonTerminal3.Rule = nonTerminal5 | Empty | commentTerminal;
		nonTerminal5.Rule = Grammar.MakeStarRule(nonTerminal5, NewLine, nonTerminal6, TermListOptions.AllowTrailingDelimiter);
		nonTerminal6.Rule = (ToTerm("Option") + "Explicit") | (ToTerm("#define") + identifierTerminal + nonTerminal24) | commentTerminal | Empty;
		nonTerminal4.Rule = nonTerminal7;
		nonTerminal7.Rule = nonTerminal8;
		nonTerminal8.Rule = nonTerminal9 | Empty;
		nonTerminal9.Rule = nonTerminal19;
		MarkTransient(nonTerminal3, nonTerminal4, nonTerminal7, nonTerminal9);
		nonTerminal19.Rule = Grammar.MakeStarRule(nonTerminal19, NewLine, nonTerminal20, TermListOptions.AllowTrailingDelimiter);
		nonTerminal20.Rule = nonTerminal51 | nonTerminal21 | nonTerminal58 | nonTerminal61 | nonTerminal68 | nonTerminal69 | nonTerminal74 | Empty;
		nonTerminal21.Rule = nonTerminal13 | nonTerminal22 | nonTerminal31 | nonTerminal32 | nonTerminal53 | nonTerminal56 | nonTerminal59 | nonTerminal60 | nonTerminal15;
		nonTerminal22.Rule = nonTerminal10 + nonTerminal23 + nonTerminal24;
		nonTerminal23.Rule = ToTerm("=") | ToTerm("+=") | "-=" | "*=" | "/=" | "<<=" | ">>=";
		MarkTransient(nonTerminal20, nonTerminal21);
		MarkTransient(nonTerminal23);
		nonTerminal51.Rule = (ToTerm("Dim") + identifierTerminal + "As" + nonTerminal52) | (ToTerm("Dim") + identifierTerminal + ToTerm("[") + nonTerminal24 + ToTerm("]") + "As" + nonTerminal52);
		nonTerminal52.Rule = ToTerm("Integer") | "Boolean";
		MarkTransient(nonTerminal52);
		MarkPunctuation("Dim", "As");
		nonTerminal10.Rule = identifierTerminal | (identifierTerminal + ToTerm("[") + nonTerminal24 + ToTerm("]"));
		nonTerminal12.Rule = identifierTerminal + ToTerm("(") + nonTerminal14 + ToTerm(")");
		nonTerminal13.Rule = identifierTerminal + ToTerm("(") + nonTerminal14 + ToTerm(")");
		nonTerminal14.Rule = Grammar.MakeStarRule(nonTerminal14, ToTerm(","), nonTerminal24);
		nonTerminal15.Rule = ToTerm("Print") + "(" + nonTerminal18 + ")";
		nonTerminal18.Rule = Grammar.MakeStarRule(nonTerminal18, ToTerm(","), nonTerminal16);
		nonTerminal16.Rule = nonTerminal17 | nonTerminal24 | stringLiteral;
		nonTerminal17.Rule = ToTerm("ToBool") + ToTerm("(") + nonTerminal24 + ToTerm(")");
		MarkTransient(nonTerminal16);
		nonTerminal25.Rule = numberLiteral | nonTerminal26 | nonTerminal10 | nonTerminal12 | nonTerminal27 | nonTerminal28 | nonTerminal29;
		nonTerminal26.Rule = ToTerm("True") | ToTerm("False");
		nonTerminal27.Rule = ToTerm("(") + nonTerminal24 + ToTerm(")");
		nonTerminal28.Rule = nonTerminal30 + nonTerminal10;
		nonTerminal29.Rule = nonTerminal10 + nonTerminal30;
		nonTerminal31.Rule = nonTerminal30 + nonTerminal10;
		nonTerminal32.Rule = nonTerminal10 + nonTerminal30;
		nonTerminal30.Rule = ToTerm("++") | ToTerm("--");
		nonTerminal24.Rule = nonTerminal42 | nonTerminal33;
		nonTerminal42.Rule = (nonTerminal33 + "Or" + nonTerminal24) | (nonTerminal33 + "XOr" + nonTerminal24);
		nonTerminal33.Rule = nonTerminal43 | nonTerminal34;
		nonTerminal43.Rule = nonTerminal34 + "And" + nonTerminal33;
		nonTerminal34.Rule = nonTerminal44 | nonTerminal35;
		nonTerminal44.Rule = "Not" + nonTerminal35;
		nonTerminal35.Rule = nonTerminal45 | nonTerminal37;
		nonTerminal45.Rule = nonTerminal37 + nonTerminal36 + nonTerminal35;
		nonTerminal37.Rule = nonTerminal46 | nonTerminal38;
		nonTerminal46.Rule = (nonTerminal37 + "<<" + nonTerminal38) | (nonTerminal37 + ">>" + nonTerminal38);
		nonTerminal38.Rule = nonTerminal47 | nonTerminal39;
		nonTerminal47.Rule = (nonTerminal38 + "+" + nonTerminal39) | (nonTerminal38 + "-" + nonTerminal39);
		nonTerminal39.Rule = nonTerminal48 | nonTerminal40;
		nonTerminal48.Rule = nonTerminal40 + "Mod" + nonTerminal39;
		nonTerminal40.Rule = nonTerminal49 | nonTerminal41;
		nonTerminal49.Rule = (nonTerminal40 + "*" + nonTerminal41) | (nonTerminal40 + "/" + nonTerminal41);
		nonTerminal41.Rule = nonTerminal50 | nonTerminal25;
		nonTerminal50.Rule = ToTerm("-") + nonTerminal25;
		nonTerminal36.Rule = ToTerm("=") | ToTerm("<>") | ToTerm("<") | ToTerm("<=") | ToTerm(">") | ToTerm(">=");
		MarkTransient(nonTerminal24, nonTerminal25, nonTerminal30, nonTerminal36, nonTerminal27);
		MarkTransient(nonTerminal33, nonTerminal34, nonTerminal35, nonTerminal36, nonTerminal37, nonTerminal38, nonTerminal39, nonTerminal40, nonTerminal41);
		MarkNotReported("++", "--");
		nonTerminal53.Rule = nonTerminal54 + nonTerminal55;
		nonTerminal54.Rule = ToTerm("Exit") | ToTerm("Continue");
		nonTerminal55.Rule = ToTerm("Do") | ToTerm("For") | ToTerm("While");
		nonTerminal56.Rule = nonTerminal57 + identifierTerminal;
		nonTerminal57.Rule = ToTerm("GoTo") | ToTerm("GoSub");
		nonTerminal58.Rule = identifierTerminal + ToTerm(":");
		nonTerminal59.Rule = ToTerm("Return");
		nonTerminal60.Rule = ToTerm("Terminate");
		MarkTransient(nonTerminal54, nonTerminal55, nonTerminal57);
		MarkPunctuation(":");
		nonTerminal61.Rule = nonTerminal62 | nonTerminal64;
		nonTerminal62.Rule = ToTerm("If") + nonTerminal24 + ToTerm("Then") + nonTerminal21 + nonTerminal63;
		nonTerminal63.Rule = (ToTerm("Else") + nonTerminal21) | Empty;
		nonTerminal64.Rule = ToTerm("If") + nonTerminal24 + nonTerminal65 + NewLine + nonTerminal19 + nonTerminal66 + ToTerm("End") + ToTerm("If");
		nonTerminal65.Rule = ToTerm("Then") | Empty;
		nonTerminal66.Rule = (ToTerm("ElseIf") + nonTerminal24 + nonTerminal65 + NewLine + nonTerminal19 + nonTerminal66) | nonTerminal67 | Empty;
		nonTerminal67.Rule = ToTerm("Else") + NewLine + nonTerminal19;
		MarkTransient(nonTerminal61, nonTerminal65);
		nonTerminal68.Rule = ToTerm("For") + nonTerminal10 + "=" + nonTerminal24 + "To" + nonTerminal24 + nonTerminal70 + NewLine + nonTerminal19 + ToTerm("Next") + nonTerminal72;
		nonTerminal69.Rule = ToTerm("For") + nonTerminal10 + "=" + nonTerminal24 + "AndWhile" + nonTerminal24 + nonTerminal71 + NewLine + nonTerminal19 + ToTerm("Next") + nonTerminal72;
		nonTerminal70.Rule = ("Step" + nonTerminal24) | Empty;
		nonTerminal71.Rule = ("Evaluate" + nonTerminal73) | Empty;
		nonTerminal73.Rule = nonTerminal22 | nonTerminal31 | nonTerminal32;
		nonTerminal72.Rule = nonTerminal10 | Empty;
		MarkTransient(nonTerminal73);
		MarkPunctuation("NEXT", "STEP", "EVALUATE");
		nonTerminal74.Rule = nonTerminal75 | nonTerminal76 | nonTerminal77;
		nonTerminal75.Rule = ToTerm("Do") + nonTerminal78 + nonTerminal24 + NewLine + nonTerminal19 + ToTerm("Loop");
		nonTerminal76.Rule = ToTerm("Do") + NewLine + nonTerminal19 + ToTerm("Loop") + nonTerminal78 + nonTerminal24;
		nonTerminal78.Rule = ToTerm("While") | ToTerm("Until");
		nonTerminal77.Rule = ToTerm("While") + nonTerminal24 + NewLine + nonTerminal19 + ToTerm("End") + ToTerm("While");
		MarkTransient(nonTerminal74, nonTerminal78);
		MarkPunctuation("LOOP", "DO");
		MarkPunctuation("(", ")", "[", "]", ",");
		RegisterBracePair("(", ")");
		RegisterBracePair("[", "]");
		LanguageFlags = LanguageFlags.CreateAst;
		Root = nonTerminal2;
	}
}
